using System;using System.IO;using System.Linq;using System.Collections.Generic;using IdleRestaurant;using UnityEngine;
public static class CleanupRoute053 {public static object Main(){var a=UnityEngine.Object.FindAnyObjectByType<RestaurantApp>();var g=new RestaurantGame(a.catalog);g.State.introComplete=true;g.State.guideStep=6;g.Now=()=>1000;for(int t=0;t<6;t++)g.State.outlets[0].dirt.Add(new CleanupMess{id=t+1,kind=0,table=t,x=-2.15f+(t%2)*4.3f,z=-2.5f+(t/2)*2+.32f});for(int t=0;t<4;t++)g.State.outlets[0].dirt.Add(new CleanupMess{id=t+7,kind=1+t%2,x=(t%3-1)*.35f,z=new[]{-4.45f,-2.15f,-.15f,1.85f}[t]});g.State.cleanupSequence=10;g.RequestCleanup(0);Physics.SyncTransforms();var collisions=new HashSet<string>();int samples=0;while(g.State.cleanupJob.active&&samples<10000){g.Tick(.05);var j=g.State.cleanupJob;Vector3 pos=a.world.room.TransformPoint(new Vector3(j.x,0,j.z));foreach(var c in Physics.OverlapCapsule(pos+Vector3.up*.30f,pos+Vector3.up*1.2f,.23f,~0,QueryTriggerInteraction.Ignore)){if(c is CharacterController||!c.transform.IsChildOf(a.world.room)||c.name=="Floor collider")continue;collisions.Add(c.name+" at "+j.x.ToString("0.00")+","+j.z.ToString("0.00"));}samples++;}var result=new{status=collisions.Count==0?"PASS":"FAIL",samples,collisions=collisions.ToArray(),radius=.23,scope="Full six-table and four-floor-mess janitor route sampled against live room's actual non-trigger static colliders; guest controllers excluded"};File.WriteAllText("/Users/playnoob/Desktop/Mahnul/GPT/restaurant-v053-cleanup/RouteAudit.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;}}
